import React from "react";
import { useNavigate } from "react-router-dom";
import "./.css";

const DoctorDashboard = () => {
  const navigate = useNavigate();

  const handleLogout = () => {
    localStorage.clear();
    navigate("/login");
  };

  return (
    <div className="doctor-dashboard-container">
      <div className="sidebar">
        <div className="sidebar-brand">MediVault Pro</div>

        
        <a href="/dashboard/doctor" className="nav-link">
          Dashboard
        </a>
        <a href="/dashboard/doctor/appointments" className="nav-link">
          Appointments
        </a>
        <a href="/dashboard/doctor/prescriptions" className="nav-link">
          Prescriptions
        </a>
        <a href="/dashboard/doctor/patients" className="nav-link">
          Patients
        </a>
      </div>

      <div className="main-content">
        <div className="topbar">
          <h3 className="welcome-text">Welcome, Dr. Strange</h3>
          <button className="logout-button" onClick={handleLogout}>
            Logout
          </button>
        </div>

        <div className="dashboard-body">
          <h2>Your Dashboard Content</h2>
          <p>Here you'll see all your required details doctor</p>
        </div>
      </div>
    </div>
  );
};

export default DoctorDashboard;
